import java.util.HashMap;
import java.util.Map;

public class RehashingDemo {
    public static void main(String[] args) {
        // Initial capacity is 4, load factor is 0.75.
        // Threshold = 4 * 0.75 = 3 items.
        Map<Integer, String> map = new HashMap<>(4, 0.75f);

        map.put(1, "One");   // Size 1: No rehash
        map.put(2, "Two");   // Size 2: No rehash
        map.put(3, "Three"); // Size 3: Hits threshold (3 >= 3)

        // The 4th insertion triggers rehashing! 
        // Capacity doubles from 4 to 8, and all elements are relocated.
        map.put(4, "Four"); 

        System.out.println("Rehashing complete. Map size: " + map.size());
    }
}
